  }
};
</script>
<style>
  body {
    background: #e9e9e9;
    margin: 0;
    padding: 30px 0;
    font-family: "Segoe Print","Comic Sans MS","KaiTi","STKaiti",cursive,sans-serif;
    display: flex;
    justify-content: center;
  }
  .page {
    position: relative;
    width: 700px;
    min-height: 1000px;
    background: #fdfdf8;
    background-image:
      linear-gradient(rgba(150,150,220,0.15) 1px, transparent 1px),
      linear-gradient(90deg, rgba(150,150,220,0.15) 1px, transparent 1px);
    background-size: 22px 22px;
    box-shadow: 0 0 12px rgba(0,0,0,0.25);
    padding: 25px 35px 50px 45px;
    box-sizing: border-box;
    color: #2b2b6b;
    font-size: 16px;
    line-height: 1.9;
  }
  .page::before {
    content: "";
    position: absolute;
    left: 0; top: 0; bottom: 0;
    width: 14px;
    background: repeating-linear-gradient(
      to bottom,
      #bbb 0px, #bbb 4px, transparent 4px, transparent 20px
    );
  }
  .cord-placeholder {
    position: absolute;
